#ifndef CHOLOPENMP_UTIL_H
#define CHOLOPENMP_UTIL_H

#include <fstream>
#include <cassert>
#include <sstream>

/*
 * Useful conversion functions int <-->size_t
 */
/*int size_t2int(size_t val) {
