inline void coordinate_system(vec3 n, vec3& t, vec3& b) {
	if (abs(n.x) > abs(n.y)) t = vec3(-n.z, 0, n.x) / sqrt(n.x * n.x + n.z * n.z);
	else t = vec3(0, n.z, -n.y) / sqrt(n.y * n.y + n.z * n.z);
