inline vec2 concentric_sample_disk(vec2 u) {
	u = vec2(u.x * 2 - 1.0f, u.y * 2 - 1.0f);
	float theta, r;
	if (abs(u.x) > abs(u.y)) {
		r = u.x; theta = PI / 4.0f * u.y / u.x;
	}
	else {
		r = u.y; theta = PI / 2.0f - PI / 4.0f * (u.x / u.y);
	}
	return r * vec2(cos(theta), sin(theta));
}

inline vec3 cosine_weighted_sample(vec2 u, vec3 n) {
	vec2 d = concentric_sample_disk(u);
	mat3 local_to_world = { 0,0,n };
	coordinate_system(n, local_to_world.x, local_to_world.y);
	return local_to_world * vec3(d.x, d.y, sqrt(1.0f - d.x * d.x - d.y * d.y));
}

template<typename F> void parallel_for(int n, F f) {
	static std::atomic<int> task_counter = 0;
	static std::vector<std::thread> threads(std::thread::hardware_concurrency() - 1);
	task_counter = 0;
	for (size_t i = 0; i < threads.size(); i++)threads[i] = std::thread([n, f, i]() {
		int offset = task_counter.fetch_add(1);
		while (offset < n) {
			f(offset); offset = task_counter.fetch_add(1);
		}
		});
	for (auto& t : threads)t.join();
}

