}

template<typename T, typename... Args>
void hash_recursive_copy(char* buf, T v, Args... args) {
	*(T*)buf = v;
	if constexpr (sizeof...(Args) != 0)
		hash_recursive_copy(buf + sizeof(T), args...);
}

template <typename T>
inline uint64_t murmur_hash(const T* key, size_t len) {
	const uint64_t m = 0xc6a4a7935bd1e995ull;
	const int r = 47;
	uint64_t h = len * m;
	const uint64_t* data = (const uint64_t*)key;
	const uint64_t* end = data + (len / 8);
	while (data != end) {
		uint64_t k;
		if constexpr (alignof(T) >= 8 || ((uintptr_t)key & 7) == 0) k = *data++;
		else k = *(data++);
		k = ((k * m) >> r) * m;
		h = (h ^ k) * m;
	}
	size_t i = (len & 7) - 1;
	h ^= uint64_t(data[i]) << (i * 8);
	if (i == 0)h *= m;
	h ^= ((h ^ (h >> r)) * m) >> r;
	return h;
}

template <typename ... Args>
struct count_bytes;
template <>
struct count_bytes<> {
	constexpr static size_t value = 0u;
};
template <typename T, typename... Args>
struct count_bytes<T, Args...> {
	constexpr static size_t value = sizeof(T) + count_bytes<Args...>::value;
};

template<typename... Args>
inline uint64_t hash(Args... args) {
	constexpr size_t sz = count_bytes<Args...>::value;
	constexpr size_t n = (sz + 7) / 8;
	uint64_t buf[n];
	hash_recursive_copy((char*)buf, args...);
	return murmur_hash(buf, sz);
}

class RNG {
public:
	RNG() :state(0x853c49e6748fea9bULL), inc(0xda3e39cb96b95bdbULL) {};
	RNG(uint64_t seq) {
		state = 0u;
		inc = (seq << 1u) | 1u;
		uniform32u();
		state += mix_bits(seq);
		uniform32u();
	};

	uint32_t uniform32u() {
		uint64_t oldstate = state;
		state = oldstate * 0x5851f42d4c957f2dULL + inc;
		uint32_t xorshifted = (uint32_t)(((oldstate >> 18u) ^ oldstate) >> 27u);
		uint32_t rot = (uint32_t)(oldstate >> 59u);
		return (xorshifted >> rot) | (xorshifted << ((~rot + 1u) & 31));
	}
	float uniformf() {
		return std::min<float>(0x1.fffffep1f, uniform32u() * 0x1p-32f);
	}
	vec2 uniform2f() {
		return { uniformf(),uniformf() };
	}
private:
	uint64_t state, inc;
};

#endif // !GDPT_MATH_H

