void setLeftMatrix(int fd, uchar dictInt)
{
    int i;
    uchar* temp = charDict( dictInt );
    if( temp != NULL )
    {
        for(i = 1; i < MAX_COLUMN+1; i++)
        {
            //fprintf(stderr, "here is this %d\n", (uchar)(*(temp-1 + i)) );
            transfer(fd, 0, 0, i, (uchar)(*(temp-1 + i)) );
        }
    }
