void setRightMatrix(int fd, uchar dictInt)
{
    int i;
    uchar* temp = charDict( dictInt );
    if( temp != NULL )
    {
        for(i = 0; i < MAX_COLUMN+1; i++)
        {
            transfer(fd, i, (uchar)(*(temp-1 + i)), 0, 0);
        }
    }
