static
setup_timer()
{
	struct itimerval	timeval;

	catch_sigalrm();

	timeval.it_value.tv_sec = 6;
	timeval.it_value.tv_usec = 0;
	timeval.it_interval.tv_sec = 6;
	timeval.it_interval.tv_usec = 0;
	setitimer( ITIMER_REAL, &timeval, NULL );
}

