{
    rs=0;			//选命令寄存器
    rw=0;           //写
    DataPort=CMD;	//写命令
    //Delay(1);		//延时，让1602准备数据
	Delay500us();
    en=1;           //使能信号变化，写入数据
    en=0;
}

