				}
			}
		}

		Timer_Count = 0;
		Led1 = !Led1;
		++Timer_Count_2;

		Timer_Count_2 &= 0x07;	//取低3位


	//		P1 &= ~0x07;
	//		P1 |= Timer_Count_2;
	//++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
		//显示时间
		Dsp_buf[6] = Timer_h/10+0x30;
		Dsp_buf[7] = (Timer_h % 10)+0x30;
		Dsp_buf[8] = ':';
		Dsp_buf[9] = Timer_m/10+0x30;
		Dsp_buf[10] = (Timer_m % 10)+0x30;
		Dsp_buf[11] = ':';
		Dsp_buf[12] = Timer_s/10+0x30;
		Dsp_buf[13] = (Timer_s % 10)+0x30;

		if (Second_flag)
		{
			Dsp_buf[8] = ':';
			Dsp_buf[11] = ':';
		}
		else
		{
			Dsp_buf[8] = ' ';
			Dsp_buf[11] = ' ';
		}

		//T1,模式设定
		TR1 = 0;        //停止计数
		ET1 = 0;        //bu允许中断
