/*----------------------------------------------------------------------*/

int IsComment(char *s)
{				/* Is Comment line ?      */
    return ((*s == '#') || (*s == '*') || IsBlank(s));
}

int IsBlank(char *s)
{				/* Is blank line ?        */
    while (isspace(*s) && *s)
	s++;
    return *s == 0;
}

int IsPsc(char *s)
{				/* Is Pseudo operation ?  */
    while (isspace(*s) && *s)
	s++;
    return *s == '.';
}

char *Rejectnl(char *s)
{				/* Reject new line character      */
    char *s1;

    s1 = s;
    while (*s)
	if (*s == '\n')
	    *s = '\0';
	else
	    s++;
    return s1;
}

char *RejectComment(char *s)
{				/* Reject Comment */
    char *s1;

    s1 = Rejectnl(s);
    while (*s)
