int spitString(const char *str, char c, char buf[10][30], int *count) {

    if (str == NULL || count == NULL) {
        return -1;
    }

    char *start = str;
    char *p = NULL;
    int i = 0; //第几行

    do {
        //"abcdef,acccd,eeee,aaaa,e3eeee,ssss,"
        p = strchr(start, c);
