  SDL_SetTextureAlphaMod(image->texture,BB_COLOR_ALPHA);
  SDL_RenderCopyEx(RENDERER,image->texture,&sr,&dr,BB_ORIENTATION,&p,SDL_FLIP_NONE);
}

