unsigned long long int bb_rect_hollow(long long int x,long long int y,long long int width,long long int height)
{
  SDL_Rect r;
  r.x = (BB_ORIGIN_X + x - width / 2) / BB_SCALE_X;
  r.y = (BB_ORIGIN_Y + y - height / 2) / BB_SCALE_Y;
