bool find132pattern(int* nums, int numsSize){
    int stack[200001];
    int idx = -1;
    int last = INT_MIN;

    for (int i = numsSize - 1; i >= 0; i--) {
        if (nums[i] < last) return true;
        while (idx != -1 && stack[idx] < nums[i])
            last = stack[idx--];
        stack[++idx] = nums[i];
    }
    return false;
}

