  printf("double         %3u\n", (uint)sizeof(double));
  printf("long double    %3u\n", (uint)sizeof(long double));

  printf("\nInteger operations\n");
  HEAD
  TEST({})
  TEST(a = 1)
  TEST(a = a + i)
  TEST(a = a - i)
  TEST(a = a * i)
  TEST(a = a / i)
  TEST(a = a % i)
  TEST(a = a << i)
  TEST(a = a >> i)
  TEST(a = a & i)
  TEST(a = a | i)
  TEST(a = a ^ i)
  TEST(a = ~i)
  TEST(a = !i)

  printf("\nFloating point operations\n");
  HEAD
  TEST(f1 = 1)
  TEST(f1 = f2 + (float)i)
  TEST(f1 = f2 - (float)i)
  TEST(f1 = f2 * (float)i)
