  TEST(a = arr[i] + a)
  TEST(a = a + arr[i])
  TEST(arr[i] = arr[i] + arr[i>>1])

  printf("\nPointers\n");
  HEAD
  TEST(ip = &a)
  TEST(*ip = 1)
  TEST(*ip = b)
  TEST(stp = &st)
  TEST(stp->a = 5)
  TEST(stp->a = b)
  TEST(obj.opf(&obj, 3))
  TEST(objp->opf(objp, 5))

  printf("\nOther Statements\n");
  HEAD
  TEST(if ( a < 5 ) b = 2)
  TEST(if ( arr[c] < 0 ) b = 2)
  TEST(a = (b < c) ? b : c)
  TEST(st.a = 1)
  TEST(a = b & st.b)
  TEST(if ( st.b ) a = b & st.b; else a = b % st.b)
  TEST(if (stp->b) a = b&stp->b; else a=b%stp->b)
  TEST(if ( !st.b ) a = b & st.b; else a = b % st.b)
  TEST(if (!stp->b) a = b&stp->b; else a=b%stp->b)
  TEST(f())
  TEST(op(&obj, 10))
  TEST(free(malloc(16)))
  TEST(free(malloc(200)))
  TEST(free(malloc(550)))
