        const int r = (pixel & 0x001F) >>  0;
        const int g = (pixel & 0x07E0) >>  5;
        const int b = (pixel & 0xF800) >> 11;
        dest[i*4+0] = r<<3 | r>>2;
        dest[i*4+1] = g<<2 | g>>4;
        dest[i*4+2] = b<<3 | b>>2;
        dest[i*4+3] = 255;
    }
