  Key_P,
  Key_Q,
  Key_R,
  Key_S,
  Key_T,
  Key_U,
  Key_V,
  Key_W,
  Key_X,
  Key_Y,
  Key_Z,
  Key_Num0 = 48,
  Key_Num1,
  Key_Num2,
  Key_Num3,
  Key_Num4,
  Key_Num5,
  Key_Num6,
  Key_Num7,
  Key_Num8,
  Key_Num9,

  // Numeric keypad.
  Key_KP_0 = 0xa0,
  Key_KP_1,
  Key_KP_2,
  Key_KP_3,
  Key_KP_4,
  Key_KP_5,
