  Key_KP_9,
  Key_KP_Multiply,
  Key_KP_Add,
  Key_KP_Enter,
  Key_KP_Subtract,
  Key_KP_Decimal,
  Key_KP_Divide,

  // Function keys.
  Key_F1 = 0xb0,
