  Key_F15,

  // Other keys.
  Key_Backspace = 8,
  Key_Tab,
  Key_Clear = 12,
  Key_Return,
  Key_Shift = 16,
  Key_Control,
  Key_Alt,
  Key_Pause,
  Key_CapsLock = 20, // Toggle
  Key_Escape = 27,
