};

static const int max_positive_for_base[17] = {
	0,
	1,
	16,
	81,
	256,
	625,
	1296,
	2401,
	4096,
	6561,
	10000,
	14641,
	20736,
	28561,
	38416,
	50625,
	65536,
};

static const int max_negative_for_base[17] = {
	-0,
	-1,
	-8,
	-27,
	-64,
	-125,
	-216,
	-343,
	-512,
	-729,
	-1000,
	-1331,
	-1728,
	-2197,
	-2744,
	-3375,
	-4096,
};

static int init_display(void)
{
	int ret;

	for (int i = 0; i < 14; i++) {
		ret = gpio_pin_configure(expander1, i, GPIO_OUTPUT | GPIO_OUTPUT_INIT_HIGH);
		if (ret) {
			printk("Error in configure pin %d on expander1: %d", i, ret);
			return ret;
		}
		ret = gpio_pin_configure(expander2, i, GPIO_OUTPUT | GPIO_OUTPUT_INIT_HIGH);
		if (ret) {
			printk("Error in configure pin %d on expander2: %d", i, ret);
			return ret;
		}
	}

	initialized = true;
	return 0;
}


int display_chars(const uint8_t chars[4])
{
	int r;
	uint16_t port1, port2;

	if (!initialized) {
		r = init_display();
		if (r) {
			return r;
		}
	}

	port1 = ((chars[3] & 0x7f) << 7) | (chars[2] & 0x7f);
	port2 = ((chars[1] & 0x7f) << 7) | (chars[0] & 0x7f);

	/* Common anode: invert the output (LOW = led on) */
	r = gpio_port_set_masked(expander1, 0x3fff, port1 ^ 0x3fff);
	if (r) {
		return r;
	}
	return gpio_port_set_masked(expander2, 0x3fff, port2 ^ 0x3fff);
}

int display_number(int num, unsigned int base)
{
	int d, i, neg = 0;
	uint8_t representation[4] = { CHAR_E, CHAR_r, CHAR_r, CHAR_OFF };

	/* Unsupported base */
	if (base > 16) {
		return -EINVAL;
	}

	/* Number too large to be displayed */
	if (num <= max_negative_for_base[base] || num >= max_positive_for_base[base]) {
		return -EINVAL;
	}

	if (num < 0) {
		num = -num;
		representation[0] = CHAR_DASH;
		neg = 1;
	}

	for (i = 3; i >= neg; i--) {
		if (num > 0 || i == 3) {
			d = num % base;
			representation[i] = digits[d];
			num /= base;
		} else {
			representation[i] = CHAR_OFF;
		}
	}
	return display_chars(representation);
}

input.dangerousExampleEn:
1. uint8_t port = 0x5aU;
2. void func(){
3.   uint16_t u16r;
4.   u16r = (~port) >> 4;
5. }
Line 4: A bitwise operation is performed on port variable. However, casting is not performed.

input.dangerousExampleKo:
1. uint8_t port = 0x5aU;
2. void func(){
3.   uint16_t u16r;
4.   u16r = (~port) >> 4;
5. }
라인 4: port 변수에 비트 연산을 수행했습니다. 하지만 즉시 타입을 캐스팅하지 않았습니다.

input.safeExampleEn:
1. uint8_t port = 0x5aU;
2. void func(){
3.   uint16_t u16r;
4.   u16r = ((uint16_t)(~port)) >> 4;
5. }
Line 4: Perform a bitwise operation on port variable, and then casting into unsigned short type.

input.safeExampleKo:
1. uint8_t port = 0x5aU;
2. void func(){
3.   uint16_t u16r;
4.   u16r = ((uint16_t)(~port)) >> 4;
5. }
라인 4: port 변수에 비트 연산을 수행한 후, 즉시 원래 타입인 unsigned short 타입으로 캐스팅합니다.

