static unsigned long _clk_24610k_get_rate(struct clk *clk)
{
	long long temp = clk_get_rate(clk->parent) * 2461LL;

	do_div(temp, 24000);

	return temp;	/* Always (UPLL * 24.61 / 240) */
}

static struct clk upll_24610k_clk = {
	.parent = &upll_clk,
	.get_rate = _clk_24610k_get_rate,
