static struct clk per_clk[] = {
	/* per_csi_clk */
	{
	 .id = 0,
	 .parent = &upll_clk,	/* can be AHB or UPLL */
	 .round_rate = _clk_perclkx_round_rate,
	 .set_rate = _clk_perclkx_set_rate,
	 .set_parent = _clk_perclkx_set_parent,
	 .get_rate = _clk_perclkx_get_rate,
