	 .get_rate = _clk_perclkx_get_rate,
	 .enable = _perclk_enable,
	 .disable = _perclk_disable,
	 .flags = RATE_PROPAGATES,
	},
	/* per_esdhc1_clk */
	{
	 .id = 3,
