    operator LPSTR()        { return mBuffer; }
    int BufferSize() const  { return mBufferSize; }
    int Length() const      { return mLength; }

private:
    char    mStackBuffer[256];
    char *  mBuffer;
    int     mBufferSize;
    int     mLength;
};

