inline static size_t wcslen_(const wchar_t *s){
	size_t ln = 0;
	while (s[ln] != L'\0'){
		if (s[++ln] == L'\0')return ln;
		if (s[++ln] == L'\0')return ln;
		if (s[++ln] == L'\0')return ln;
		++ln;
	}return ln;
}

