    }

    void set1(uint16_t x) {
        detail::simdlib::set1(data, &vdupq_n_u16, x);
    }

    simd16uint16 operator*(const simd16uint16& other) const {
        return simd16uint16{
                detail::simdlib::binary_func(data, other.data, &vmulq_u16)};
