                return simd16uint16{detail::simdlib::unary_func(
                        data, detail::simdlib::vshlq<9>)};
            case 10:
                return simd16uint16{detail::simdlib::unary_func(
                        data, detail::simdlib::vshlq<10>)};
            case 11:
                return simd16uint16{detail::simdlib::unary_func(
                        data, detail::simdlib::vshlq<11>)};
            case 12:
                return simd16uint16{detail::simdlib::unary_func(
