		if (x >= 0x1000) {

			if (x >= 0x4000) {

				return (table[x >> 8]);

			} else {

				return (table[x >> 6] >> 1);

			}

		} else if (x >= 0x400) {

			return (table[x >> 4] >> 2);

		} else {

			return (table[x >> 2] >> 3);

		}

	} else if (x >= 0) {

		return table[x] >> 4;

	}



	//hm, x was negative....

