// main()
//------------------
int main() {
	volatile unsigned int pushbutton, count = 0xF;
	volatile unsigned int j = 1;

	delay();

	while(1) {

		*WRITE_IO(IO_LEDR) = count;

		if (j == 1) {
		    count = count << 1;
		    if (count == 0xf000)
		        j = 0;
		} else {
				count = count >> 1;
		    if (count == 0x000f)
		        j = 1;
		}

		inline_assembly();	  

		delay();

	}

	return 0;
}

void delay() {
	volatile unsigned int j;

	for (j = 0; j < (100000); j++) ;	// delay 
}

