GL_RET silabs_ble_read_char(BLE_MAC address, int char_handle)
{
    int connection = 0;
    char address_str[BLE_MAC_LEN] = {0};
    addr2str(address, address_str);
    GL_RET ret = ble_dev_mgr_get_connection(address_str, &connection);
    if (ret != GL_SUCCESS)
    {
        return GL_ERR_PARAM;
