{
public:
    virtual void setZoom(float zoom, float origin) = 0;
    virtual void update(const QRect& r = QRect()) = 0;
    virtual void setGeometry(const QRect& r) = 0;
    virtual void SetTimeMarker(float marker) = 0;
};

