    void SetFPS(float fps); // Only referred to if MarkerStyle == MARKER_STYLE_FRAMES.
    float GetFPS() const
    {
        return m_fps;
    }

    void SetPlayCallback(const std::function<void()>& callback);

Q_SIGNALS:
