static int MPI_Allgatherv(const void *sendbuf, int sendcount,
                          MPI_Datatype sendtype, void *recvbuf, int *recvcounts,
                          int *displs, MPI_Datatype recvtype, MPI_Comm comm)
{
    *recvcounts = 1;
