	scalarPart = inv_fast_sqrt((1L<<30) - inv_q30_mult(inQuat[0], inQuat[0])
		- inv_q30_mult(inQuat[1], inQuat[1])
		- inv_q30_mult(inQuat[2], inQuat[2]) );
	outQuat[0] = scalarPart;
	outQuat[1] = inQuat[0];
	outQuat[2] = inQuat[1];
	outQuat[3] = inQuat[2];

	return 0;
}

