#pragma once
namespace Hazel
{
	class EngineTimer
	{
	public:

		static void Init(void);

		static long long GetCurrent(void);

		static inline double ToSeconds(long long ticks)
		{
			return ticks * s_Delta;
		}

		static inline double ToMilliseconds(long long ticks)
		{
			return ticks * s_Delta * 1000.0;
		}

	private:
		static double s_Delta;
	};

	class Timer
	{
	public:

		Timer()
		{
			m_Start = 0ll;
			m_Elapsed = 0ll;
		}

		void Start()
		{
			if (m_Start == 0ll)
			{
				m_Start = EngineTimer::GetCurrent();
			}
		}

		void Stop()
		{
			if (m_Start != 0ll)
			{
				m_Elapsed += EngineTimer::GetCurrent() - m_Start;
				m_Start = 0ll;
			}
		}

		void Reset()
		{
			m_Elapsed = 0ll;
			m_Start = 0ll;
		}

		long long GetDelta() const
		{
			return m_Elapsed;
		}

		double GetDeltaInSeconds() const
		{
			return EngineTimer::ToSeconds(m_Elapsed);
		}

		double GetDeltaInMillisecons() const
		{
			return EngineTimer::ToMilliseconds(m_Elapsed);
		}

	private:
		long long m_Start;
		long long m_Elapsed;
	};
}

