struct Proceso_HIST {
	uchar isHistG, isHist1x3D, isHist3x1D;
	Extractor *ex;
	int64_t csHist, totalBinsHist, lengthDesc, zonesH, zonesW;
	double *histogram;
	IplImage *img_cshistOne, *img_cshistAll, *img_bgrAll, *bg_cshistOne;
