              if (bl.refreshScreen.isMax()) toOGL(bl, hDC);
              bl.solve(true);
              bl.refreshScreen++;


          }
      }

      bl.udt.clear();
      bQuit = false;
      while (!bQuit)
      {
          /* check for messages */
          if (PeekMessage (&msg, NULL, 0, 0, PM_REMOVE))
          {
              /* handle or dispatch messages */
              if (msg.message == WM_QUIT)
              {
                  bQuit = TRUE;
              }
              else
              {
                  TranslateMessage (&msg);
                  DispatchMessage (&msg);
              }
          }
          else
          {
        //      bl.setForces3();
              toOGL(bl, hDC);
              bQuit = true;

          }
      }


      return bl;
  }
};

