			sum7 += alpha * Beta[curr_rel_segment_index][k*HAP_NUMBER + 7];
		}
		HProbs[h1*HAP_NUMBER+0] = sum0;
		HProbs[h1*HAP_NUMBER+1] = sum1;
		HProbs[h1*HAP_NUMBER+2] = sum2;
