template <class T>
void Vector<T>::fill(const size_t initsize, const T initvalue)  {
  ShortIterator<T>::ptr= begin;
  for (size_t cnt= initsize; cnt; --cnt)
    *(ShortIterator<T>::ptr)++ = initvalue;
  return;
}

