  filt2 = (v16i8)__msa_splati_h(filt, 2);
  filt3 = (v16i8)__msa_splati_h(filt, 3);

  LOAD_7VECS_SB(src, src_stride, src0, src1, src2, src3, src4, src5, src6);
  src += (7 * src_stride);

