                  src0, src1, src2, src3, src4, src5, src6, 128);

  ILVR_B_6VECS_SB(src0, src2, src4, src1, src3, src5,
                  src1, src3, src5, src2, src4, src6,
                  src10_r, src32_r, src54_r, src21_r, src43_r, src65_r);

