                                 filt0, filt1, filt2, filt3);
    out2_r = FILT_8TAP_DPADD_S_H(src32_r, src54_r, src76_r, src98_r,
                                 filt0, filt1, filt2, filt3);
    out3_r = FILT_8TAP_DPADD_S_H(src43_r, src65_r, src87_r, src109_r,
                                 filt0, filt1, filt2, filt3);

    out0_r = SRARI_SATURATE_SIGNED_H(out0_r, FILTER_BITS, 7);
