/* comefrom: DoDisasters ScenarioDisaster */
MakeEarthquake(void)
{
  register short x, y, z;
  short time;

  DoEarthQuake();

  SendMesAt(-23, CCx, CCy);
  time = Rand(700) + 300;
  for (z = 0; z < time; z++)  {
    x = Rand(WORLD_X - 1);
    y = Rand(WORLD_Y - 1);
    if ((x < 0) || (x > (WORLD_X - 1)) ||
	(y < 0) || (y > (WORLD_Y - 1)))
      continue;
    /* TILE_IS_VULNERABLE(Map[x][y]) */
    if (Vunerable(Map[x][y])) {
      if (z & 0x3)
	Map[x][y] = (RUBBLE + BULLBIT) + (Rand16() & 3);
      else
	Map[x][y] = (FIRE + ANIMBIT) + (Rand16() & 7);
    }
  }
}


/* comefrom: DoDisasters */
SetFire(void)
{
  register short x, y, z;

  x = Rand(WORLD_X - 1);
  y = Rand(WORLD_Y - 1);
  z = Map[x][y];
  /* TILE_IS_ARSONABLE(z) */
  if (!(z & ZONEBIT)) {
    z = z & LOMASK;
    if ((z > LHTHR) && (z < LASTZONE)) {
      Map[x][y] = FIRE + ANIMBIT + (Rand16() & 7);
      CrashX = x; CrashY = y;
      SendMesAt(-20, x, y);
    }
  }
}


/* comefrom: DoDisasters */
MakeFire(void)
{
  short t, x, y, z;
  for (t = 0; t < 40; t++)  {
    x = Rand(WORLD_X - 1);
    y = Rand(WORLD_Y - 1);
    z = Map[x][y];
    /* !(z & BURNBIT) && TILE_IS_ARSONABLE(z) */
    if ((!(z & ZONEBIT)) && (z & BURNBIT)) {
      z = z & LOMASK;
      if ((z > 21) && (z < LASTZONE)) {
	Map[x][y] = FIRE + ANIMBIT + (Rand16() & 7);
	SendMesAt(20, x, y);
	return;
      }
    }
  }
}


/* comefrom: MakeEarthquake */
Vunerable(int tem)
{
  register int tem2;

  tem2 = tem & LOMASK;
  if ((tem2 < RESBASE) ||
      (tem2 > LASTZONE) ||
      (tem & ZONEBIT))
    return(FALSE);
  return(TRUE);
}


