		if (BZ2_bzCompressInit(&(ret->strm.bzstrm), compression_level, 0, 30) != 0){
			log_error("Failed to initialize compression operation");
			free(ret);
			return NULL;
		}
	}
	else{
		ret->strm.bzstrm.next_in = NULL;
		ret->strm.zstrm.avail_in = 0;

