int read_int(){
	int minus = 0;
	int result = 0;
	int ch = getchar();
	while (1) {
		if (ch == '-')
			break;
		if (ch >= '0' && ch <= '9')
			break;
		ch = getchar();
	}
	if (ch == '-') minus = 1;
	else result = ch - '0';
	while (1){
		ch = getchar();
		if (ch < '0' || ch > '9') break;
		result = result * 10 + (ch - '0');
	}
	if (minus)
		return -result;
	else
		return result;
}

void bubbleSort(int arr[], int n)
{
	int i, j;
	for (i = 0; i < n - 1; i++)
		for (j = 0; j < n - i - 1; j++)
			if (arr[j] > arr[j + 1]) {
				int tmp = arr[j];
				arr[j] = arr[j + 1];
				arr[j + 1] = tmp;
