/* ast */

#define MAKEAST(type) Ast *ast_make_##type 

MAKEAST(unit) (void);
MAKEAST(integer) (int value);
MAKEAST(float) (double value);
MAKEAST(bool) (bool value);
MAKEAST(string) (char *value);
