class Display
{
  public:
    static void update();
    static void drawCreature(const Creature &creature, bool showIndicator=true);
    static void drawParticle(const Particle &particle);
    static void setTonePacing(uint8_t t, uint8_t p);
    static int getNumShapes() {return numShapes;}
    static bool isOnScreen(const Point &point)
    {
      if (point.x < 0)
        return false;
      if (point.x >= 220)
        return false;
      if (point.y < 0)
        return false;
      if (point.y >= 176)
        return false;
      return true;
    }
  private:
    struct InternalPoint
    {
      int16_t x;
      int16_t y;
    };
    struct InternalLine
    {
      InternalPoint p;
      InternalPoint end;
      InternalPoint d;
      int16_t sx;
      int16_t err;
    };
    struct InternalCircle
    {
      InternalPoint center;
      int16_t radius;
    };
    struct InternalTriangle
    {
      InternalPoint p1;
      InternalPoint p2;
      InternalPoint p3;
