void test_eq(const char* code, const T val, const U expected) {

    try {
        count ++;
        if (!equal(val, expected)) {
            failed++;
            for (auto& it : section) {
                if (it.second) {
                    printf("%sSection: %s\n", indent(), it.first);
                    it.second = false;
                }
            }
            try {
                printf("%sFAILURE in ‘%s’:\n%s  Expected: ‘%s’\n%s   but got: ‘%s’\n",
