static starxy_t* field1() {
    starxy_t* starxy;
    double field[14];
    int i=0, N;
    // star0 A: (0,0)
    field[i++] = 0.0;
    field[i++] = 0.0;
    // star1 B: (2,2)
    field[i++] = 2.0;
    field[i++] = 2.0;
    // star2
    field[i++] = -1.0;
    field[i++] = 3.0;
    // star3
    field[i++] = 0.5;
    field[i++] = 1.5;
    // star4
    field[i++] = 1.0;
    field[i++] = 1.0;
    // star5
    field[i++] = 1.5;
    field[i++] = 0.5;
    // star6
    field[i++] = 3.0;
    field[i++] = -1.0;

    N = i/2;
    starxy = starxy_new(N, FALSE, FALSE);
    for (i=0; i<N; i++) {
        starxy_setx(starxy, i, field[i*2+0]);
        starxy_sety(starxy, i, field[i*2+1]);
    }
	return starxy;
}

void test1() {
	int i;
    solver_t* solver;
    index_t index;
    starxy_t* starxy;
    int wanted[][4] = { { 0,1,3,4 },
                         { 0,2,3,4 },
                         { 1,2,3,4 },
                         { 2,5,0,1 },
                         { 2,5,0,3 },
                         { 2,5,0,4 },
                         { 2,5,1,3 },
                         { 2,5,1,4 },
                         { 2,5,3,4 },
                         { 0,1,3,5 },
