        fillRGBA(x, y, 5, 7, 0, 0, 0, a); // background
    fillRGBA(x, y, 1, 7, r, g, b, a); // first vertical line
    fillRGBA(x+1, y, 2, 1, r, g, b, a); // first bar
    fillRGBA(x+1, y+3, 2, 1, r, g, b, a); // second bar
    fillRGBA(x+1, y+6, 2, 1, r, g, b, a); // last bar
