/**
## Changes

* The number of `ghosts` is set to 4
* all `#included` files have a `grid/` prefix.
 */
#include "grid/mempool.h"

#define TWO_ONE 1 // enforce 2:1 refinement ratio
#define GHOSTS 4
/* By default only one layer of ghost cells is used on the boundary to
   optimise the cost of boundary conditions. */

#ifndef BGHOSTS
@ define BGHOSTS 1
#endif

#define _I     (point.i - GHOSTS)
#if dimension >= 2
# define _J    (point.j - GHOSTS)
#endif
#if dimension >= 3
# define _K    (point.k - GHOSTS)
#endif
#define _DELTA (1./(1 << point.level))

typedef struct {
  unsigned short flags;
  // number of refined neighbors in a 3^dimension neighborhood
  unsigned short neighbors;
  int pid; // process id
} Cell;

enum {
  active    = 1 << 0,
  leaf      = 1 << 1,
  border    = 1 << 2,
  vertex    = 1 << 3,
  user      = 4,

  face_x = 1 << 0
#if dimension >= 2
  , face_y = 1 << 1
#endif
#if dimension >= 3
  , face_z = 1 << 2
#endif
};

@define is_active(cell)  ((cell).flags & active)
@define is_leaf(cell)    ((cell).flags & leaf)
@define is_coarse()      ((cell).neighbors > 0)
@define is_border(cell)  ((cell).flags & border)
@define is_local(cell)   ((cell).pid == pid())
@define is_vertex(cell)  ((cell).flags & vertex)

// Caches

typedef struct {
  int i;
#if dimension >= 2
  int j;
#endif
#if dimension >= 3
  int k;
#endif  
} IndexLevel;

typedef struct {
  IndexLevel * p;
  int n, nm;
} CacheLevel;

typedef struct {
  int i;
#if dimension >= 2
  int j;
#endif
#if dimension >= 3
  int k;
#endif  
  int level, flags;
} Index;

typedef struct {
  Index * p;
  int n, nm;
} Cache;

#if dimension > 1
// Refcounted array

static char * new_refarray (size_t len, size_t size) {
  return (char *) calloc (len + 1, size);
}

static void refarray (void * p, size_t len, size_t size) {
  int * refcount = (int *)(((char *)p) + len*size);
  (*refcount)++;
}

static bool unrefarray (void * p, size_t len, size_t size) {
  int * refcount = (int *)(((char *)p) + len*size);
  (*refcount)--;
  if (*refcount == 0) {
    free (p);
    return true;
  }
  return false;
}
#endif // dimension > 1

// Layer

typedef struct {
#if dimension == 1
  char ** m;      // the 1D array of data  
#elif dimension == 2
  char *** m;     // the 2D array of data
#else // dimension == 3
  char **** m;    // the 3D array of data
#endif
  Mempool * pool; // the memory pool actually holding the data
  int nc;     // the number of allocated columns
  int len;    // the (1D) size of the array
} Layer;

static size_t _size (size_t depth)
{
  return (1 << depth) + 2*GHOSTS;
}

static size_t poolsize (size_t depth, size_t size)
{
  // the maximum amount of data at a given level
#if dimension == 1
  return _size(depth)*size;  
#elif dimension == 2
  return sq(_size(depth))*size;
#else
  return cube(_size(depth))*size;
#endif
}

foreach_dimension()
static inline
void assign_periodic_x (void ** m, int i, int nl, void * b)
{
  m[i] = b;
  if (Period.x) {
    for (int j = i; j < nl + 2*GHOSTS; j += nl)
      m[j] = b;
    for (int j = i - nl; j >= 0; j -= nl)
      m[j] = b;
  }
}

static Layer * new_layer (int depth)
{
  Layer * l = qmalloc (1, Layer);
  l->len = _size (depth);
  if (depth == 0)
    l->pool = NULL; // the root layer does not use a pool
  else {
    size_t size = sizeof(Cell) + datasize;
    // the block size is 2^dimension*size because we allocate
    // 2^dimension children at a time
    l->pool = mempool_new (poolsize (depth, size), (1 << dimension)*size);
  }
#if dimension == 1
  l->m = qcalloc (l->len, char *);
#elif dimension == 2
  l->m = qcalloc (l->len, char **);
#elif dimension == 3
  l->m = qcalloc (l->len, char ***);
#endif
  l->nc = 0;
  return l;
}

static void destroy_layer (Layer * l)
{
  if (l->pool)
    mempool_destroy (l->pool);
  free (l->m);
  free (l);
}

#if dimension == 1
static void layer_add_row (Layer * l, int i)
{
  l->nc++;
}

static bool layer_remove_row (Layer * l, int i)
{
  if (--l->nc == 0) {
    destroy_layer (l);
    return true; // layer has been destroyed
  }
  assert (l->nc >= 0);
  return false;
}
#else // dimension != 1
static void layer_add_row (Layer * l, int i, int j)
{
  if (!l->m[i]) {
    assign_periodic_x ((void **) l->m, i, l->len - 2*GHOSTS,
		       (void *) new_refarray (l->len, sizeof (char *)));
    l->nc++;
  }
  refarray (l->m[i], l->len, sizeof(char *));
#if dimension > 2
  if (!l->m[i][j])
    assign_periodic_y ((void **) l->m[i], j, l->len - 2*GHOSTS,
		       (void *) new_refarray (l->len, sizeof (char *)));
  refarray (l->m[i][j], l->len, sizeof(char *));
#endif
}

static bool layer_remove_row (Layer * l, int i, int j)
{
#if dimension > 2
  if (unrefarray (l->m[i][j], l->len, sizeof (char *)))
    assign_periodic_y ((void **) l->m[i], j, l->len - 2*GHOSTS, NULL);
#endif
  if (unrefarray (l->m[i], l->len, sizeof (char *))) {
    assign_periodic_x ((void **) l->m, i, l->len - 2*GHOSTS, NULL);
    if (--l->nc == 0) {
      destroy_layer (l);
      return true; // layer has been destroyed
    }
    assert (l->nc >= 0);
  }
  return false;
}
#endif // dimension != 1

