static void update_depth (int inc)
{
  Tree * q = tree;
  grid->depth += inc;
  q->L = &(q->L[-1]);
  qrealloc (q->L, grid->depth + 2, Layer *);
  q->L = &(q->L[1]);
  if (inc > 0)
    q->L[grid->depth] = new_layer (grid->depth);
  cache_level_resize (active, inc);
  cache_level_resize (prolongation, inc);
  cache_level_resize (boundary, inc);
  cache_level_resize (restriction, inc);
}

static void alloc_children (Point point)
{
  if (point.level == grid->depth)
    update_depth (+1);
  else if (allocated_child(0,0,0))
    return;

  /* low-level memory management */
  Layer * L = tree->L[point.level + 1];
  size_t len = sizeof(Cell) + datasize;
  char * b = (char *) mempool_alloc0 (L->pool);
  int nl = L->len - 2*GHOSTS;
  int i = 2*point.i - GHOSTS;
  for (int k = 0; k < 2; k++, i++) {
#if dimension == 1
    layer_add_row (L, i);
    assert (!L->m[i]);
    assign_periodic_x ((void **) L->m, i, nl, (void *) b);
    b += len;
#elif dimension == 2
    layer_add_row (L, i, 0);
    int j = 2*point.j - GHOSTS;
    for (int l = 0; l < 2; l++, j++) {
      assert (!L->m[i][j]);
      assign_periodic_y ((void **) L->m[i], j, nl, (void *) b);
      b += len;
    }
#else // dimension == 3
    int j = 2*point.j - GHOSTS;
    for (int l = 0; l < 2; l++, j++) {
      layer_add_row (L, i, j);
      int m = 2*point.k - GHOSTS;
      for (int n = 0; n < 2; n++, m++) {
	assert (!L->m[i][j][m]);
	assign_periodic_z ((void **) L->m[i][j], m, nl, (void *) b);
	b += len;
      }
    }
#endif
  }

  int pid = cell.pid;
  foreach_child() {
    cell.pid = pid;
@if TRASH
    for (scalar s in all)
      s[] = undefined;
@endif    
  }
}

#if dimension == 1 
static void free_children (Point point)
{
  /* low-level memory management */
  Layer * L = tree->L[point.level + 1];
  int i = 2*point.i - GHOSTS, nl = L->len - 2*GHOSTS;
  assert (L->m[i]);
  mempool_free (L->pool, L->m[i]);
  for (int k = 0; k < 2; k++, i++) {
    assign_periodic_x ((void **) L->m, i, nl, NULL);
    if (layer_remove_row (L, i)) {
      assert (point.level + 1 == grid->depth);
      update_depth (-1);
    }
  }
}
#elif dimension == 2
static void free_children (Point point)
{
  /* low-level memory management */
  Layer * L = tree->L[point.level + 1];
  int i = 2*point.i - GHOSTS, nl = L->len - 2*GHOSTS;
  assert (L->m[i][2*point.j - GHOSTS]);
  mempool_free (L->pool, L->m[i][2*point.j - GHOSTS]);
  for (int k = 0; k < 2; k++, i++) {
    int j = 2*point.j - GHOSTS;
    for (int l = 0; l < 2; l++, j++)
      assign_periodic_y ((void **) L->m[i], j, nl, NULL);
    if (layer_remove_row (L, i, j)) {
      assert (point.level + 1 == grid->depth);
      update_depth (-1);
    }
  }
}
#else // dimension == 3
static void free_children (Point point)
{
  /* low-level memory management */
  Layer * L = tree->L[point.level + 1];
  int i = 2*point.i - GHOSTS, nl = L->len - 2*GHOSTS;
  assert (L->m[i][2*point.j - GHOSTS][2*point.k - GHOSTS]);
  mempool_free (L->pool, L->m[i][2*point.j - GHOSTS][2*point.k - GHOSTS]);
  for (int k = 0; k < 2; k++, i++) {
    int j = 2*point.j - GHOSTS;
    for (int l = 0; l < 2; l++, j++) {
      int m = 2*point.k - GHOSTS;
      for (int n = 0; n < 2; n++, m++)
	assign_periodic_z ((void **) L->m[i][j], m, nl, NULL);
      if (layer_remove_row (L, i, j)) {
	assert (point.level + 1 == grid->depth);
	update_depth (-1);
      }
    }
  }
}
#endif // dimension == 3

void increment_neighbors (Point point)
{
  tree->dirty = true;
  if (cell.neighbors++ == 0)
    alloc_children (point);
  foreach_neighbor (GHOSTS/2)
    if (cell.neighbors++ == 0)
      alloc_children (point);
  cell.neighbors--;
}

void decrement_neighbors (Point point)
{
  tree->dirty = true;
  foreach_neighbor (GHOSTS/2)
    if (allocated(0)) {
      cell.neighbors--;
      if (cell.neighbors == 0)
	free_children (point);
    }
  if (cell.neighbors) {
    int pid = cell.pid;
    foreach_child() {
      cell.flags = 0;
      cell.pid = pid;
    }
  }
}

static void apply_periodic_elem (char ** m, int len)
{
  if (m) {
    int end = len - GHOSTS;
    for (int k = 0; k < GHOSTS; k++) {
      m[k] = m[k + end - GHOSTS];
      m[end + k] = m[k + GHOSTS];
    }
  }
}

static void apply_periodic (Tree * q)
{
#if dimension == 1
  if (Period.x) {
    for (int i = 0; i < q->L[0]->len; i++)
      q->L[0]->m[i] = q->L[0]->m[GHOSTS];
    for (int l = 1; l <= depth(); l++)
      apply_periodic_elem ((char **) q->L[l]->m, q->L[l]->len);
  }
#elif dimension == 2
  if (Period.y) {
    for (int i = 0; i < q->L[0]->len; i++)
      for (int j = 0; j < q->L[0]->len; j++)
	q->L[0]->m[i][j] = q->L[0]->m[i][GHOSTS];
    for (int l = 1; l <= depth(); l++) {
      Layer * L = q->L[l];
      for (int i = 0; i < L->len; i++)
	apply_periodic_elem (L->m[i], L->len);
    }
  }
#else // dimension == 3
  if (Period.z) {
    for (int i = 0; i < q->L[0]->len; i++)
      for (int j = 0; j < q->L[0]->len; j++)
	for (int k = 0; k < q->L[0]->len; k++)
	  q->L[0]->m[i][j][k] = q->L[0]->m[i][j][GHOSTS];
    for (int l = 1; l <= depth(); l++) {
      Layer * L = q->L[l];
      for (int i = 0; i < L->len; i++)
	if (L->m[i])
	  for (int j = 0; j < L->len; j++)
	    apply_periodic_elem (L->m[i][j], L->len);
    }
  }
#endif // dimension == 3
}

void realloc_scalar (int size)
{
  /* low-level memory management */
  Tree * q = tree;
  size_t oldlen = sizeof(Cell) + datasize;
  size_t newlen = oldlen + size;
  datasize += size;
  /* the root level is allocated differently */
  Layer * L = q->L[0];
  int len = L->len;
  for (int i = Period.x*GHOSTS; i < len - Period.x*GHOSTS; i++) {
#if dimension == 1
    qrealloc (L->m[i], newlen, char);
#else // dimension != 1
    for (int j = Period.y*GHOSTS; j < len - Period.y*GHOSTS; j++) {
#if dimension == 2
      qrealloc (L->m[i][j], newlen, char);
#else
      for (int k = Period.z*GHOSTS; k < len - Period.z*GHOSTS; k++)
	qrealloc (L->m[i][j][k], newlen, char);
#endif
    }
#endif // dimension != 1
  }
  /* all other levels */
  for (int l = 1; l <= depth(); l++) {
    Layer * L = q->L[l];
    int len = L->len;
    Mempool * oldpool = L->pool;
    L->pool = mempool_new (poolsize (l, newlen), (1 << dimension)*newlen);
    for (int i = Period.x*GHOSTS; i < len - Period.x*GHOSTS; i += 2)
      if (L->m[i]) {
#if dimension == 1
	char * new = (char *) mempool_alloc (L->pool);
	for (int k = 0; k < 2; k++) {
	  memcpy (new, L->m[i+k], oldlen);
	  L->m[i+k] = new;
	  new += newlen;
	}
#else // dimension >= 2
	for (int j = Period.y*GHOSTS; j < len - Period.y*GHOSTS; j += 2)
	  if (L->m[i][j]) {
#if dimension == 2
	    char * new = (char *) mempool_alloc (L->pool);
	    for (int k = 0; k < 2; k++)
	      for (int o = 0; o < 2; o++) {
		memcpy (new, L->m[i+k][j+o], oldlen);
		L->m[i+k][j+o] = new;
		new += newlen;
	      }
#else // dimension == 3
	    for (int k = Period.z*GHOSTS; k < len - Period.z*GHOSTS; k += 2)
	      if (L->m[i][j][k]) {
		char * new = (char *) mempool_alloc (L->pool);
		for (int l = 0; l < 2; l++)
		  for (int m = 0; m < 2; m++)
		    for (int n = 0; n < 2; n++) {
		      memcpy (new, L->m[i+l][j+m][k+n], oldlen);
		      L->m[i+l][j+m][k+n] = new;
		      new += newlen;
		    }
	      }
#endif // dimension == 3
	  }
#endif // dimension >= 2
      }
    mempool_destroy (oldpool);
  }
  apply_periodic (q);
  check_periodic (q);
}

/* Boundaries */

@define VN v.x
@define VT v.y
@define VR v.z

#define is_neighbor(...) (allocated(__VA_ARGS__) && \
			  !is_boundary(neighbor(__VA_ARGS__)))

@if _MPI // fixme
@ define disable_fpe_for_mpi() disable_fpe (FE_DIVBYZERO|FE_INVALID)
@ define enable_fpe_for_mpi()  enable_fpe (FE_DIVBYZERO|FE_INVALID)
@else
@ define disable_fpe_for_mpi()
@ define enable_fpe_for_mpi()
@endif

static inline void no_restriction (Point point, scalar s);

static bool normal_neighbor (Point point, scalar * scalars, vector * vectors)
{
  for (int k = 1; k <= BGHOSTS; k++)
    foreach_dimension()
      for (int i = -k; i <= k; i += 2*k)
	if (is_neighbor(i)) {
	  Point neighbor = neighborp(i);
	  int id = bid(cell);
	  for (scalar s in scalars)
	    s[] = s.boundary[id](neighbor, point, s, NULL);
	  for (vector v in vectors) {
	    scalar vn = VN;
	    v.x[] = vn.boundary[id](neighbor, point, v.x, NULL);
#if dimension >= 2
	    scalar vt = VT;
	    v.y[] = vt.boundary[id](neighbor, point, v.y, NULL);
#endif
#if dimension >= 3
	    scalar vr = VR;
	    v.z[] = vr.boundary[id](neighbor, point, v.z, NULL);
#endif
	  }
	  return true;
	}
  return false;
}

static bool diagonal_neighbor_2D (Point point,
				  scalar * scalars, vector * vectors)
{
#if dimension >= 2
  for (int k = 1; k <= BGHOSTS; k++)
#if dimension == 3
    foreach_dimension()
#endif
      for (int i = -k; i <= k; i += 2*k)
	for (int j = -k; j <= k; j += 2*k)
	  if (allocated(i,j) && is_neighbor(i,j) &&
	      allocated(i,0) && is_boundary(neighbor(i,0)) &&
	      allocated(0,j) && is_boundary(neighbor(0,j))) {
	    Point n = neighborp(i,j),
	      n1 = neighborp(i,0), n2 = neighborp(0,j);
	    int id1 = bid(neighbor(i,0)), id2 = bid(neighbor(0,j));
	    for (scalar s in scalars)
	      s[] = (s.boundary[id1](n,n1,s,NULL) +
		     s.boundary[id2](n,n2,s,NULL) -
		     s[i,j]);
	    for (vector v in vectors) {
	      scalar vt = VT, vn = VN;
	      v.x[] = (vt.boundary[id1](n,n1,v.x,NULL) +
		       vn.boundary[id2](n,n2,v.x,NULL) -
		       v.x[i,j]);
	      v.y[] = (vn.boundary[id1](n,n1,v.y,NULL) +
		       vt.boundary[id2](n,n2,v.y,NULL) -
		       v.y[i,j]);
#if dimension == 3
	      scalar vr = VR;
	      v.z[] = (vr.boundary[id1](n,n1,v.z,NULL) +
		       vr.boundary[id2](n,n2,v.z,NULL) -
		       v.z[i,j]);
#endif
	    }
	    return true;
	  }
#endif // dimension >= 2
  return false;
}

static bool diagonal_neighbor_3D (Point point,
				  scalar * scalars, vector * vectors)
{
#if dimension == 3
  for (int n = 1; n <= BGHOSTS; n++)
    for (int i = -n; i <= n; i += 2*n)
      for (int j = -n; j <= n; j += 2*n)
	for (int k = -n; k <= n; k += 2*n)
	  if (is_neighbor(i,j,k) &&
	      is_boundary(neighbor(i,j,0)) &&
	      is_boundary(neighbor(i,0,k)) &&
	      is_boundary(neighbor(0,j,k))) {
	    Point
	      n0 = neighborp(i,j,k),
	      n1 = neighborp(i,j,0),
	      n2 = neighborp(i,0,k),
	      n3 = neighborp(0,j,k);
	    int
	      id1 = bid(neighbor(i,j,0)),
	      id2 = bid(neighbor(i,0,k)),
	      id3 = bid(neighbor(0,j,k));
	    for (scalar s in scalars)
	      s[] = (s.boundary[id1](n0,n1,s,NULL) +
		     s.boundary[id2](n0,n2,s,NULL) +
		     s.boundary[id3](n0,n3,s,NULL) -
		     2.*s[i,j,k]);
	    for (vector v in vectors) {
	      scalar vt = VT, vn = VN, vr = VR;
	      v.x[] = (vt.boundary[id1](n0,n1,v.x,NULL) +
		       vt.boundary[id2](n0,n2,v.x,NULL) +
		       vn.boundary[id3](n0,n3,v.x,NULL) -
		       2.*v.x[i,j,k]);
	      v.y[] = (vt.boundary[id1](n0,n1,v.y,NULL) +
		       vn.boundary[id2](n0,n2,v.y,NULL) +
		       vt.boundary[id3](n0,n3,v.y,NULL) -
		       2.*v.y[i,j,k]);
	      v.z[] = (vn.boundary[id1](n0,n1,v.z,NULL) +
		       vr.boundary[id2](n0,n2,v.z,NULL) +
		       vr.boundary[id3](n0,n3,v.z,NULL) -
		       2.*v.z[i,j,k]);
	    }
	    return true;
	  }
#endif
  return false;
}

#if dimension > 1
foreach_dimension()
static Point tangential_neighbor_x (Point point, bool * zn)
{
  for (int k = 1; k <= BGHOSTS; k++)
    for (int j = -k; j <= k; j += 2*k) {
      if (is_neighbor(0,j) || is_neighbor(-1,j)) {
	*zn = false;
	return neighborp(0,j);
      }
#if dimension == 3
      // fixme: what about diagonals?
      if (is_neighbor(0,0,j) || is_neighbor(-1,0,j)) {
	*zn = true;
	return neighborp(0,0,j);
      }
#endif // dimension == 3
    }
  return (Point){.level = -1};
}
#endif // dimension > 1

static inline bool is_boundary_point (Point point) {
  return is_boundary (cell);
}

static void box_boundary_level (const Boundary * b, scalar * list, int l)
{
  disable_fpe_for_mpi();
  scalar * scalars = NULL;
  vector * vectors = NULL, * faces = NULL;
  for (scalar s in list)
    if (!is_constant(s) && s.refine != no_restriction) {
      if (s.v.x.i == s.i) {
	if (s.face)
	  faces = vectors_add (faces, s.v);
	else
	  vectors = vectors_add (vectors, s.v);
      }
      else if (s.v.x.i < 0 && s.boundary[0])
	scalars = list_add (scalars, s);
    }

  foreach_boundary_level (l) {
    if (!normal_neighbor (point, scalars, vectors) &&
	!diagonal_neighbor_2D (point, scalars, vectors) &&
	!diagonal_neighbor_3D (point, scalars, vectors)) {
      // no neighbors
      for (scalar s in scalars)
	s[] = undefined;
      for (vector v in vectors)
	foreach_dimension()
	  v.x[] = undefined;
    }
    if (faces) {
      int id = bid(cell);
      foreach_dimension()
	for (int i = -1; i <= 1; i += 2) {
	  // normal neighbor for faces
	  if (is_neighbor(i)) {
	    Point neighbor = neighborp(i);
	    for (vector v in faces) {
	      scalar vn = VN;
	      if (vn.boundary[id])
		v.x[(i + 1)/2] = vn.boundary[id](neighbor, point, v.x, NULL);
	    }
	  }
#if dimension > 1
	  else if (i == -1) {
	    // tangential neighbor
	    bool zn;
	    Point neighbor = tangential_neighbor_x (point, &zn);
	    if (neighbor.level >= 0) {
	      int id = is_boundary_point (neighbor) ?
		bid(neighbor(-1)) : bid(cell);
	      for (vector v in faces) {
#if dimension == 2
		scalar vt = VT;
#else // dimension == 3
		scalar vt = zn ? VT : VR;
#endif
		v.x[] = vt.boundary[id](neighbor, point, v.x, NULL);
	      }
	    }
	    else
	      // no neighbor
	      for (vector v in faces)
		v.x[] = 0.;
	  }
#endif // dimension > 1
	}
    }
  }

  free (scalars);
  free (vectors);
  free (faces);
  enable_fpe_for_mpi();
}

#undef is_neighbor

@undef VN
@undef VT
@define VN _attribute[s.i].v.x
@define VT _attribute[s.i].v.y

static double masked_average (Point point, scalar s)
{
  double sum = 0., n = 0.;
  foreach_child()
    if (!is_boundary(cell) && s[] != nodata)
      sum += s[], n++;
  return n ? sum/n : nodata;
}

foreach_dimension()
static double masked_average_x (Point point, scalar s)
{
  double sum = 0., n = 0.;
  foreach_child()
    if (child.x < 0 && (!is_boundary(cell) || !is_boundary(neighbor(1))) &&
	s[1] != nodata)
      sum += s[1], n++;
  return n ? sum/n : nodata;
}

static void masked_boundary_restriction (const Boundary * b,
					 scalar * list, int l)
{
  scalar * scalars = NULL;
  vector * faces = NULL;
  for (scalar s in list)
    if (!is_constant(s) && s.refine != no_restriction) {
      if (s.v.x.i == s.i && s.face)
	faces = vectors_add (faces, s.v);
      else
	scalars = list_add (scalars, s);
    }

  foreach_halo (restriction, l) {
    for (scalar s in scalars)
      s[] = masked_average (parent, s);
    for (vector v in faces)
      foreach_dimension() {
	double average = masked_average_x (parent, v.x);
	if (is_boundary(neighbor(-1)))
	  v.x[] = average;
	if (is_boundary(neighbor(1)))
	  v.x[1] = average;
      }
  }

  free (scalars);
  free (faces);  
}

