 public:
  void clear() {
    samples_.clear();
  }

  // The segment is from (x_1, y_1) to (x_2, y_2).
  // The first sample is start_distance from (x_1, y_1).
  void sample_segment(
      double x_1, double y_1, double x_2, double y_2,
