        x *= multiply.x;
        y *= multiply.y;
        return *this;
    }
    PrecXY& operator/=(const PrecXY& divide) {
        x /= divide.x;
        y /= divide.y;
        return *this;
    }

    bool operator==(const PrecXY& comp) const {
        return (x == comp.x) && (y == comp.y);
    }

    bool operator!=(const PrecXY& comp) const {
