    proc->plist->recvpost = (int *) malloc (proc->plist->num * sizeof(int));
    for(j=0;j<Volpex_numprocs;j++){
      tproc = Volpex_get_proc_byid(j);

      if(proc->rank_MCW == tproc->rank_MCW){
		if((tproc->level-mylevel)<0)
