int nk_nesl_init()
{
    INFO("init\n");
    return 0;
}


int nk_nesl_exec(void *vcode)
{
    INFO("execute program at %p\n",vcode);
    if (vcode==0) {
	INFO("Using built-in test\n");
	vcode = programstr;
    }

    // flag config
    check_args   = 0;
    debug_flag   = 1;
    lex_trace    = 0;
    stack_trace  = 0;
    command_trace= 1;
    value_trace  = 0;
    runtime_trace= 0;
    program_dump = 1;
    link_trace   = 0;
    heap_trace   = 0;
    abort_on_error = 0;
    timer        = 0;
    // vstack_size_init = ...

    uint64_t size = strlen(vcode);
    void *tmp = malloc(size+1);
    if (!tmp) {
	ERROR("Failed to allocate temporary copy of program\n");
	return -1;
    }
    strcpy(tmp,vcode);

    nesl_exec(tmp);

    free(tmp);

    return 0;
}

