static int
dcmd_Handles(uintptr_t addr, uint_t flags, int argc, const mdb_arg_t *argv)
{
	Rt_map		rtmap;
	char		*str;
	uint_t		flg = 0;
	APlist		apl;
	uintptr_t	datap, nitems;
	Grp_hdl		*ghp;

	/*
	 * Insure we have a valid address, and provide for a -v option.
	 */
	if ((flags & DCMD_ADDRSPEC) == 0) {
