	mdb_printf(MSG_ORIG(MSG_STR_DASHES));

	if (HANDLES(&rtmap) == 0)
		return (DCMD_OK);

	addr = (uintptr_t)HANDLES(&rtmap);
	if (mdb_vread(&apl, sizeof (APlist), addr) == -1) {
		mdb_warn(MSG_ORIG(MSG_ERR_READ), MSG_ORIG(MSG_STR_APLIST),
		    addr);
