		return -1; //Fail to open the file
	}
	while(1){
		fscanf(fp,"%d",&array[i++]);
		if(feof(fp)){
			break;
		}
	}
	return i;
}

int is_sorted(int array[],int length){
	int i;
	for(i=0;i<length-1;++i){
		if(array[i]>array[i+1]){
			return 0;
		}
	}
	return 1;
}

