        return;

    if (regNumber > CTR_REG_SIZE) {
        printf("setCfgReg: Wrong reg number :%08X!\n", regNumber);
        return;
    }
    xpdma_writeReg(fpga, regNumber*4 + CTR_REG_OFFSET, data);
