#include "semphr.h"
#include "task.h"
#include "stdbool.h"

#define SENSOR_ADDR                     0x3A

/* registers and register bit patterns */

#define STATUS_M                    0x07
#define OUT_X_L_M                   0x08
#define OUT_X_H_M                   0x09
#define OUT_Y_L_M                   0x0A
