                buffer |= (uint16_t)(USB_HOST_BITMBW_32);
            }
#else
            buffer &= (uint16_t)~(USB_HOST_BITCURPIPE);
#endif
            USB201.D0FIFOSEL = buffer;

            for (loop = 0; loop < 4; loop++)
