            if (dfacc != 0)
            {
                dummy = USB201.D0FIFO.UINT32;
            }
#endif

            buffer &= (uint16_t)~(USB_HOST_BITCURPIPE | USB_HOST_BITMBW);
            buffer |= (uint16_t)(pipe | mbw);
