                                USB_PIPEnTRE_TRENB);
            RZA_IO_RegWrite_16(&USB201.PIPE5TRE,
                                1,
                                USB_PIPEnTRE_TRCLR_SHIFT,
                                USB_PIPEnTRE_TRCLR);
        break;

        case USB_HOST_PIPE9:
            RZA_IO_RegWrite_16(&USB201.PIPE9TRE,
                                0,
                                USB_PIPEnTRE_TRENB_SHIFT,
                                USB_PIPEnTRE_TRENB);
