char		*ft_pwd(void)
{
	char *str;

	if (!(str = (char*)malloc(sizeof(char) * 4028 + 1)))
		return (NULL);
	getcwd(str, 4028);
	return (str);
}

static int	check_is_slash(char *str)
{
	int	i;

	i = 0;
	while (str[i])
	{
		if (i == 0 && (str[i] == '/' || str[i] == '\'' || str[i] == '\"'))
			return (1);
		else if (str[i] == '/')
			return (2);
		i++;
	}
	return (0);
}

