#ifndef __SCV_SPRING_H__
#define __SCV_SPRING_H__

#include <climits>

namespace scv {

class Spring {
public:
   enum Alignment {
      CENTER, LEADING, TRAILING, NALIGNMENT = -1
   };

   enum Size {
      UNSET = INT_MIN,
      DEFAULT_SIZE = -1,
      PREFERRED_SIZE = -2
   };

