/* IEEE 802.15.4-2015, Table 7-2 in Section 7.2.1.5 */
static panid_test_def panid_table_0b10[] = {
  /* dest_addr, src_addr, dest_panid,  src_panid,   panid_cmp */
  {  NO_ADDR,   NO_ADDR,  NOT_PRESENT, NOT_PRESENT, OFF}, // index 0,  row-1
