		if (session == 0 && connect_rc == 0) {
			rc = 0;
		} else {
			rc = -EINVAL;
			goto exit_connect;
		}
		break;
	/* previous session */
	case 0:
	/* TODO */
	/* FALLTHROUGH */
	default:
		rc = -EINVAL;
		goto exit_connect;
