t_list		*ft_lstnew(void const *content, size_t content_size)
{
	t_list		*out;

	if ((out = (t_list *)malloc(sizeof(t_list))) == NULL)
		return (NULL);
	if (content == NULL || content_size == 0)
	{
		out->content = NULL;
		out->content_size = 0;
		out->next = NULL;
		return (out);
	}
	out->content = ft_memdup(content, content_size);
	out->content_size = content_size;
	out->next = NULL;
	return (out);
}

