{
  testlib_init(argc, argv);
  MPS_ARGS_BEGIN(args) {
    MPS_ARGS_ADD(args, MPS_KEY_ARENA_SIZE, 600000);
    testit((ArenaClass)mps_arena_class_vm(), args);
  } MPS_ARGS_END(args);
  printf("%s: Conclusion: Failed to find any defects.\n", argv[0]);
  return 0;
}


