  spawner = create_compound_spawner(FLOOR_GRASS_SHORT, -1 , spawn_point.x, spawn_point.y);
  add_spawner_to_plane(main, spawner);

  add_compound_to_plane(main, wall_comp);
  add_plane(basic, main);
  return basic;
