void	termios_init(void)
{
	struct termios	term;

	if (tcgetattr(0, &term) != 0)
		return ;
	term.c_lflag &= ~ECHOCTL;
	if (tcsetattr(0, TCSANOW, &term) != 0)
		return ;
}

