				else
					printf_s(logger_buff.c_str());
				break;
			default:
				if (nullptr != logCallBack)
				{
					logCallBack(logger_buff.c_str());
					//logtype = 1;
				}
				else
					printf_s(logger_buff.c_str());
				break;
		}
		return 0;
	}
