int M(int l, int r)
{
	int ans = 1;

	for(int i = l; i <= r; i++)
	{
		ans *= a[i] % n;
		ans %= n;
	}
	ans %= n;

	return ans;
}

int H(int l, int r)
{
	int ans;

	if(l == r)
	{
		return a[l];
	}

	ans = a[l] ^ a[l + 1];
	for(int i = l + 2; i <= r; i++)
	{
		ans = ans ^ a[i];
	}
	return ans;
}

