*/

#ifndef _STDIO_HEADERS_H
#include "stdio_headers.h"
#endif /* _STDIO_HEADERS_H */

#undef putc_unlocked

int
putc_unlocked(int c, FILE *stream) {
    int result = EOF;

    assert(stream != NULL);

    if (stream == NULL) {
        __set_errno(EFAULT);
        goto out;
    }

    result = __putc_unlocked(c, stream);

out:

    return (result);
}

