void board_overcurrent_event(int port)
{
	if (port == 0) {
		/* TODO(b/111281797): When does this get set high again? */
		gpio_set_level(GPIO_USB_OC_ODL, 0);
		cprints(CC_USBPD, "p%d: overcurrent!", port);
	}
