uint32 constitem_hash(void *k)
{
  uint32 hash = 0;
  ConstItem *item = k;
  switch (item->type) {
  case CONST_INT:
    hash = hash_uint32((uint32)item->ival, 32);
    break;
  case CONST_FLOAT:
    hash = hash_uint32((intptr_t)item, 32);
    break;
  case CONST_BOOL:
    hash = hash_uint32((intptr_t)item, 32);
    break;
  case CONST_STRING:
    hash = hash_uint32((uint32)item->index, 32);
    break;
  case CONST_UCHAR:
    hash = hash_uint32((uint32)item->uch.val, 32);
    break;
  default:
    assert(0);
    break;
  }

  return hash;
}

int constitem_equal(void *k1, void *k2)
{
  int res = 0;
  ConstItem *item1 = k1;
  ConstItem *item2 = k2;
  if (item1->type != item2->type)
    return 0;
  switch (item1->type) {
  case CONST_INT:
    res = (item1->ival == item2->ival);
    break;
  case CONST_FLOAT:
    res = (item1->fval == item2->fval);
    break;
  case CONST_BOOL:
    res = (item1 == item2);
    break;
  case CONST_STRING:
    res = (item1->index == item2->index);
    break;
  case CONST_UCHAR:
    res = item1->uch.val == item2->uch.val;
    break;
  default:
    assert(0);
    break;
  }
  return res;
}

