								add_to_secrets_list(realms,(char*)realm);
							}
						}
					} else {
						printf("%s[%s]\n",kval,rval);
					}
				}
			}
			ret = 0;
		}
		if(res) {
			PQclear(res);
		}
	}
	return ret;
