static const VDRIID VDRIID_STREAMING_OUTPUT_CONNECTOR = 0x80000012;

//! Output Connector Interface
class IStreamingOutputConnector : public virtual IStreamingConnector,
                                  public virtual IStreamingDataPacketManager
   {
   public:
