                 struct file *file,
                 unsigned int ioctl_num,
                 unsigned long ioctl_param)
#else
static long device_ioctl(struct file *file,
                 unsigned int ioctl_num,
                 unsigned long ioctl_param)
#endif
{
    unsigned long cr3 = read_cr3();
    switch(ioctl_num) {
        case IOCTL_GET_CR3:
            put_user(cr3,(long *)ioctl_param);
            break;
        default:
            return -1;
    }
    return 0;
}

