/**
 * print_diagonal - draw a diagonal line in the terminal.
 * @n: number of times the character '\' should be printed.
 *
 */
void print_diagonal(int n)
{
	int i, j, spaces;

	spaces = 0;
	for (i = n; i > 0; i--)
	{
		for (j = spaces; j > 0; j--)
			_putchar(' ');
		_putchar(92);
		_putchar('\n');
		spaces++;
	}
	if (spaces < 1)
		_putchar('\n');
}

