            nErrorInfoSet(&errorInfo, error, errorTime, infoStr, infoLen),
             NULL, 0);
            nCrashSafe(error, errorInfo);
            /* NO RETURN */
    }
}
#endif

NIMBLE_INLINE
void _nEngineSetSignalHandler(void)
{
#if NIMBLE_OS == NIMBLE_WINDOWS
    SetUnhandledExceptionFilter(&_nEngineHandleException);
#else
    struct sigaction sa = {};
    sa.sa_handler = &_nEngineHandleException;
#  define einfoStr "sigemptyset() failed in _nEngineSetSignalHandler(), "\
 "and the signal handlers could not be set."
    nAssert(
     !sigemptyset(&sa.sa_mask),
     NERROR_INTERNAL_FAILURE,
     einfoStr,
     NCONST_STRLEN(einfoStr)
    ); 
#  undef einfoStr
#  if NIMBLE_OS == NIMBLE_MACOS
    sa.sa_flags = SA_SIGINFO;
#  else
    sa.sa_flags = SA_SIGINFO | SA_ONSTACK;

    /* Create new stack for signal handler. */
    stack_t ss;
    ss.ss_sp = nAlloc(SIGSTKSZ);
    ss.ss_size = SIGSTKSZ;
    ss_flags = 0;
#    define einfoStr "sigaltstack() failed in _nEngineSetSignalHandler(), "\
 "and the signal handlers could not be set."
    nAssert(
     !sigaltstack(&ss, NULL),
     NERROR_INTERNAL_FAILURE,
     einfoStr,
     NCONST_STRLEN(einfoStr)
    );
#    undef einfoStr
#  endif

#  define einfoStr "sigaction() failed in _nEngineSetSignalHandler(), and "\
 "the signal handlers could not be set."
    nAssert(!sigaction(SIGTERM, &sa, NULL),
     NERROR_INTERNAL_FAILURE, einfoStr, NCONST_STRLEN(einfoStr));
    nAssert(!sigaction(SIGABRT, &sa, NULL),
     NERROR_INTERNAL_FAILURE, einfoStr, NCONST_STRLEN(einfoStr));
    nAssert(!sigaction(SIGFPE, &sa, NULL),
     NERROR_INTERNAL_FAILURE, einfoStr, NCONST_STRLEN(einfoStr));
    nAssert(!sigaction(SIGILL, &sa, NULL),
     NERROR_INTERNAL_FAILURE, einfoStr, NCONST_STRLEN(einfoStr));
    nAssert(!sigaction(SIGINT, &sa, NULL),
     NERROR_INTERNAL_FAILURE, einfoStr, NCONST_STRLEN(einfoStr));
    nAssert(!sigaction(SIGSEGV, &sa, NULL),
     NERROR_INTERNAL_FAILURE, einfoStr, NCONST_STRLEN(einfoStr));
#endif
}

int nEngineInit(
 char **restrict args,
 const int argc,
 char *restrict nrtmPath,
 size_t nrtmPathLen,
 const char *const restrict crashLogPath,
 size_t crashLogPathLen,
 void (*const errorCallback) (const nErrorInfo_t *const errorInfo),
 void (*const crashCallback) (const nErrorInfo_t *const errorInfo)
)
{
#define einfoStr "nEngineInit() was called, but Nimble is already initialized."
    if (nErrorAssert(
     !NIMBLE_INITIALIZED,
     NERROR_WARN,
     einfoStr,
     NCONST_STRLEN(einfoStr)
    )) return NERROR_WARN;
#undef einfoStr

    /* Add _nEngineCleanup() to the exit functions. */
#define einfoStr "atexit() failed in nEngineInit(), and the exit functions "\
 "could not be set."
    nAssert(
     !atexit(&_nEngineCleanup),
     NERROR_INTERNAL_FAILURE,
     einfoStr,
     NCONST_STRLEN(einfoStr)
    );
#undef einfoStr

    /* Set callbacks. */
    _nEngineSetSignalHandler();
    nErrorSetCallback(errorCallback);
    nCrashSetCallback(crashCallback);

    /* Set global ARG variables. */
    NIMBLE_ARGC = nStringCopyArray(&NIMBLE_ARGS, args, argc);
#define einfoStr "No arguments passed to nEngineInit(). This is necessary "\
 "even if no arguments are sent, as the first argument is always the "\
 "executable file."
    nAssert(
     NIMBLE_ARGC,
     NERROR_NULL,
     einfoStr,
     NCONST_STRLEN(einfoStr)
    );
#undef einfoStr
    _nFileSetExecutablePath();

    /* Get process instance for Windows. */
#if NIMBLE_OS == NIMBLE_WINDOWS
    NINSTANCE = GetModuleHandle(NULL);
#define einfoStr "GetModuleHandle() failed in nEngineInit(), and the instance "\
 "could not be set."
    nAssert(
     NINSTANCE != NULL,
     NERROR_INTERNAL_FAILURE,
     einfoStr,
     NCONST_STRLEN(einfoStr)
    );
#undef einfoStr
#endif

    /* Start Nimble Runtime Manager. */
#define NRTM_ARGC 3
    char **nrtmArgs = nAlloc(sizeof(char *) * NRTM_ARGC);

    char *nrtmPathStr;
    if (nrtmPath)
    {
        if (nrtmPathLen <= 0) nrtmPathLen = strlen(nrtmPath);
        nrtmPathStr = nFileRealPath(nrtmPath, NULL);
    }
    else
    {
        nrtmPathStr = nAlloc(NEXEC_DIR_LEN + NCONST_STRLEN(NRTM_EXEC) + 1);
        nStringCopy(nrtmPathStr, NEXEC_DIR, NEXEC_DIR_LEN);
        nStringCopy(nrtmPathStr + NEXEC_DIR_LEN, NRTM_EXEC, NCONST_STRLEN(NRTM_EXEC));
    }
    nrtmArgs[0] = nrtmPathStr;
    if (crashLogPathLen <= 0) crashLogPathLen = strlen(crashLogPath);
    nrtmArgs[2] = nStringDuplicate(crashLogPath, crashLogPathLen);

#if NIMBLE_OS == NIMBLE_WINDOWS
    char idBuffer[33];
    const int pid = GetCurrentProcessId();
    itoa(pid, idBuffer, 10);
    nrtmArgs[1] = nStringDuplicate(idBuffer, strlen(idBuffer));
    char *commandLine = nStringJoin(" ", 1, NULL, nrtmArgs, NRTM_ARGC);

    STARTUPINFO si = {};
    PROCESS_INFORMATION pi = {};
    si.cb = sizeof(si);
#  define einfoStr "CreateProcess() failed in nEngineInit(), and Nimble "\
 "Runtime Manager could not be launched."
    nAssert(
     CreateProcessA(NULL, commandLine, NULL, NULL, 0, 0, NULL, NULL, &si, &pi),
     NERROR_INTERNAL_FAILURE,
     einfoStr,
     NCONST_STRLEN(einfoStr)
    );
#  undef einfoStr
#else
    const int pid = GetCurrentProcessId();
    char idBuffer[33];
    itoa(pid, idBuffer, 10);
    nrtmArgs[1] = nStringDuplicate(idBuffer, strlen(idBuffer));
    char *commandLine = nStringJoin(" ", 1, NULL, nrtmArgs, NIMBLE_ARGC);

    const int res = fork();
#  define einfoStr "fork() failed in nEngineInit(), and Nimble Runtime "\
 "Manager could not be launched."
    nAssert(
     res == 0 || res == 1,
     NERROR_INTERNAL_FAILURE,
     einfoStr,
     NCONST_STRLEN(einfoStr)
    );
#  undef einfoStr

    if (!res)
    {
        // Child process
#  define einfoStr "execv() failed in nEngineInit(), and Nimble Runtime "\
 "Manager could not be launched."
        nAssert(
         execv(nrtmPathStr, commandLine),
         NERROR_INTERNAL_FAILURE,
         einfoStr,
         NCONST_STRLEN(einfoStr);
        );
#  undef einfoStr
    }

#endif
    nFree((void **) &commandLine);
    nFree((void **) &nrtmArgs[0]);
    nFree((void **) &nrtmArgs[1]);
    nFree((void **) &nrtmArgs[2]);
    nFree((void **) &nrtmArgs);

    _nGraphicsInit();

    // Setup mutexes
#define einfoStr "Could not create mutex with nThreadMutexCreate() "\
 "in nEngineInit()."
    nAssert(
     !nThreadMutexCreate(&nStacktraceMutex),
     NERROR_INTERNAL_FAILURE,
     einfoStr,
     NCONST_STRLEN(einfoStr)
    );
#undef einfoStr

    NIMBLE_INITIALIZED = 1;
    return NSUCCESS;
}

// NimbleEngine.c

