//==================================================================================================
//==================================================================================================
String CachedGraphicsURL2filename(String url) {
  int idx;
  do {
    idx = url.indexOf("/");
    if (idx != -1) {
      url.remove(0, idx + 1);
    }
  } while (idx != -1);

  return cachedimageprefix + url;
}

//==================================================================================================
//==================================================================================================
void CachedGraphicsFetchUnCached(const String url) {
  String filename = CachedGraphicsURL2filename(url);

  if (! SPIFFS.exists(filename) ) {
    SerialUDP.println("Download: " + url);

    HTTPClient http;
    http.begin(imageproxyloaderurl + url);
    int httpCode = http.GET();
    if (httpCode > 0) {
      if (httpCode == HTTP_CODE_OK) {
        // get lenght of document (is -1 when Server sends no Content-Length header)
        int len = http.getSize();
        // create buffer for read
        uint8_t buff[128] = { 0 };

        File file = SPIFFS.open(filename, "w");

        // get tcp stream
        WiFiClient * stream = http.getStreamPtr();

        int cc = 0;

        // read all data from server
        while (http.connected() && (len > 0 || len == -1)) {
          // get available data size
          size_t size = stream->available();

          if (size) {
            // read up to 128 byte
            int c = stream->readBytes(buff, ((size > sizeof(buff)) ? sizeof(buff) : size));

            cc = cc + c;

            // write it to Serial
            file.write(buff, c);

            if (len > 0) {
              len -= c;
            }
          }
          delay(1);
        }
        file.close();
      }
    }
    http.end();
  }
}


