  crossprod(1.0, &x, &c);
  double t_op = get_time(t0);

  MPI_print(&g, "crossprod,%d,%d,%d,%d,%d,%d,%d,%f,%f\n", g.size, g.nprow, g.npcol, m, n, mb, nb, t_gen, t_op);

  dmat_free(&x);
  dmat_free(&c);
  grid_finalize(&g);

  return EXIT_OK;
}

